const CATALOG = [{"id":"case-file","mode":"reframe","name":"Case File","verb":"scan","family":"REFRAME","minutes":3,"parents":["Beliefs / Evidence","Social / Team / Perspective","Uncertainty / Future Worry / Reassurance"],"cast":["glitch","patch","drop","rush","still","sync"],"poster":{"char":"glitch","mood":"smug"},"tagline":"Inspector Glitch closed your case in 0.3 seconds. Reopen it.","why":"For a scary conclusion: separate what a camera saw from what your brain added.","flagship":true,"n":1,"file":"case-file.7a8d07ae93.js"},{"id":"map-of-maybes","mode":"reframe","name":"Map of Maybes","verb":"route","family":"REFRAME","minutes":2,"parents":["Uncertainty / Future Worry / Reassurance","Beliefs / Evidence"],"cast":["glitch"],"poster":{"char":"glitch","mood":"cool"},"tagline":"Drive every road the facts allow. The fear is one district.","why":"For a story stuck on one ending: drive every explanation the facts allow, then pick a hunch.","n":2,"file":"map-of-maybes.83260c4253.js"},{"id":"prediction-vault","mode":"reframe","name":"Prediction Vault","verb":"seal","family":"REFRAME","minutes":2,"parents":["Uncertainty / Future Worry / Reassurance","Performance / Confidence"],"cast":["glitch"],"poster":{"char":"glitch","mood":"cool"},"tagline":"Seal your prediction in the vault. Reality opens it later.","why":"For a fear about what will happen: write it as a prediction, set the odds, check it on the day.","n":3,"file":"prediction-vault.5e13a81ef2.js"},{"id":"missing-scene","mode":"reframe","name":"Missing Scene","verb":"splice","family":"REFRAME","minutes":2,"parents":["Memory / Replay / Rumination","Social / Team / Perspective"],"cast":["drop"],"poster":{"char":"drop","mood":"happy"},"tagline":"Splice the missing scenes into a memory on repeat. Then roll it.","why":"For a moment you keep replaying: add the context the replay cut out, then watch it again.","n":4,"file":"missing-scene.3832c3e56e.js"},{"id":"mood-glasses","mode":"reframe","name":"Mood Glasses","verb":"swap","family":"REFRAME","minutes":2,"parents":["Emotion","Beliefs / Evidence"],"cast":["sync"],"poster":{"char":"sync","mood":"rainbow"},"tagline":"Swap four lenses on the same street. See what the feeling adds.","why":"When a feeling feels like proof: compare the fear lens with the facts, then pick a fairer pair.","n":5,"file":"mood-glasses.8637ea97d6.js"},{"id":"late-night-line","mode":"reframe","name":"Late Night Line","verb":"mix","family":"REFRAME","minutes":2,"parents":["Identity / Self","Inner Speech / Mental Text","Social / Team / Perspective"],"cast":["patch"],"poster":{"char":"patch","mood":"cosy"},"tagline":"Host a 2am call-in. Mix a kind, fair reply. Then hear who called.","why":"For a harsh inner voice: answer yourself the way you would answer a friend.","n":6,"file":"late-night-line.9370992d37.js"},{"id":"time-telescope","mode":"reframe","name":"Time Telescope","verb":"focus","family":"REFRAME","minutes":2,"parents":["Decision Pressure","Uncertainty / Future Worry / Reassurance","Values / Meaning / Grief"],"cast":["drop"],"poster":{"char":"drop","mood":"wow"},"tagline":"Turn the ring: see your worry from 10 minutes, months and years away.","why":"For a worry that fills the sky: the 10-10-10 view from the future shrinks it to size, honestly.","n":7,"file":"time-telescope.cfee3963a3.js"},{"id":"spectrum-factory","mode":"reframe","name":"Spectrum Factory","verb":"blend","family":"REFRAME","minutes":2,"parents":["Performance / Confidence","Identity / Self","Beliefs / Evidence"],"cast":["patch"],"poster":{"char":"patch","mood":"idea"},"tagline":"Black-and-white label? Blend its real colour on a 0-100 spectrum.","why":"For all-or-nothing verdicts: anchor a 0-100 line with real examples, then place what happened.","n":8,"file":"spectrum-factory.8fbfff3042.js"},{"id":"scale-shop","mode":"reframe","name":"Scale Shop","verb":"weigh","family":"REFRAME","minutes":2,"parents":["Mental Overload / Working Memory","Uncertainty / Future Worry / Reassurance","Emotion"],"cast":["rush"],"poster":{"char":"rush","mood":"determined"},"tagline":"It feels like a 10. Weigh it against real things on a brass scale.","why":"When a worry feels enormous: compare it with everyday mishaps to find its real weight.","n":9,"file":"scale-shop.52836df7d2.js"},{"id":"responsibility-pie","mode":"reframe","name":"Responsibility Pie","verb":"slice","family":"REFRAME","minutes":2,"parents":["Social / Team / Perspective","Identity / Self","Communication / Boundaries"],"cast":["patch"],"poster":{"char":"patch","mood":"cosy"},"tagline":"Feels all your fault? Bake a pie of every cause and slice it fairly.","why":"For self-blame: list every factor that played a part, then size your share honestly.","n":10,"file":"responsibility-pie.7154bbd271.js"},{"id":"objection","mode":"reframe","name":"Objection!","verb":"object","family":"REFRAME","minutes":2,"parents":["Beliefs / Evidence","Inner Speech / Mental Text","Social / Team / Perspective"],"cast":["glitch","patch","still"],"poster":{"char":"glitch","mood":"determined"},"tagline":"Your inner critic is prosecuting. Shout OBJECTION! at every trap.","why":"For a harsh inner voice: catch each thinking trap as it’s said, name it, then say it fairly.","n":11,"file":"objection.82a55f3712.js"},{"id":"worst-case-plinko","mode":"reframe","name":"Worst-Case Plinko","verb":"drop","family":"REFRAME","minutes":2,"parents":["Uncertainty / Future Worry / Reassurance","Decision Pressure","Panic / Body Alarm"],"cast":["rush","glitch"],"poster":{"char":"rush","mood":"surprised"},"tagline":"Your worst case needs a chain of bad luck. Drop 100 balls and see.","why":"For a worst case that feels certain: multiply the honest odds, then plan how you’d cope.","n":12,"file":"worst-case-plinko.4bdea21929.js"},{"id":"sticker-shock","mode":"reframe","name":"Sticker Shock","verb":"peel","family":"REFRAME","minutes":2,"parents":["Identity / Self","Performance / Confidence","Inner Speech / Mental Text"],"cast":["patch","sync","drop"],"poster":{"char":"patch","mood":"determined"},"tagline":"Peel the harsh labels off, slowly. See what’s really underneath.","why":"For a harsh label on yourself: swap it for something specific and fair.","n":13,"file":"sticker-shock.862ee9ea93.js"},{"id":"should-forge","mode":"reframe","name":"Should Forge","verb":"forge","family":"REFRAME","minutes":2,"parents":["Inner Speech / Mental Text","Performance / Confidence","Communication / Boundaries"],"cast":["rush","still"],"poster":{"char":"rush","mood":"determined"},"tagline":"Heat your “should”, hammer it on the beat, bend it into a preference.","why":"For rigid shoulds and musts: keep what you value, lose the command.","n":14,"file":"should-forge.14224b0417.js"},{"id":"spotlight","mode":"reframe","name":"Spotlight","verb":"sweep","family":"REFRAME","minutes":2,"parents":["Social / Team / Perspective","Performance / Confidence","Memory / Replay / Rumination"],"cast":["patch","rush","sync","glitch"],"poster":{"char":"patch","mood":"shy"},"tagline":"Sweep the spotlight over the audience and read their minds.","why":"For “everyone noticed”: see what the audience is really thinking about (mostly lunch).","n":15,"file":"spotlight.e99863e168.js"},{"id":"gold-pan","mode":"reframe","name":"Gold Pan","verb":"swirl","family":"REFRAME","minutes":2,"parents":["Emotion","Positive State","Beliefs / Evidence"],"cast":["drop","rush"],"poster":{"char":"drop","mood":"happy"},"tagline":"Swirl your day like a prospector. Keep the gold, toss the fool’s gold.","why":"For a low mood that keeps only the bad bits: pan for the true facts it washed out.","n":16,"file":"gold-pan.09b3bf7b38.js"},{"id":"body-radio","mode":"reframe","name":"Body Radio","verb":"tune","family":"REFRAME","minutes":2,"parents":["Panic / Body Alarm","Uncertainty / Future Worry / Reassurance","Emotion"],"cast":["still","sync"],"poster":{"char":"still","mood":"music"},"tagline":"Tune your body from Station Danger to the station that explains it.","why":"For a racing heart or a dizzy, buzzing body: hear it as revving up, not danger.","n":17,"file":"body-radio.01a5d18740.js"},{"id":"claw-machine","mode":"reframe","name":"Claw Machine","verb":"grab","family":"REFRAME","minutes":2,"parents":["Overthinking / Thought Fusion","Decision Pressure","Mental Overload / Working Memory"],"cast":["loopie","glitch","rush"],"poster":{"char":"loopie","mood":"wow"},"tagline":"Grab the thoughts you keep gripping. Weigh them. Let go of one.","why":"For a head full of thoughts you can’t put down: weigh what each costs, then loosen your grip.","n":18,"file":"claw-machine.062e7b9211.js"},{"id":"night-shift","mode":"reframe","name":"Night Shift","verb":"scrub","family":"REFRAME","minutes":2,"parents":["Sleep / Winding Down","Uncertainty / Future Worry / Reassurance","Overthinking / Thought Fusion"],"cast":["still","loopie","drop"],"poster":{"char":"still","mood":"sleepy"},"tagline":"At 3 a.m. it’s a monster on the wall. Drag the sun up and look again.","why":"For a 3 a.m. worry: see it in daylight, then give it an appointment and sleep.","n":19,"file":"night-shift.e5f1ce8cd5.js"},{"id":"thought-train","mode":"reframe","name":"Thought Train","verb":"switch","family":"REFRAME","minutes":2,"parents":["Overthinking / Thought Fusion","Inner Speech / Mental Text","Beliefs / Evidence"],"cast":["loopie","glitch"],"poster":{"char":"loopie","mood":"think"},"tagline":"Facts to the main line, stories to the Maybe siding. On the beat.","why":"For a story on repeat: sort what a camera could film from what your mind added.","n":20,"file":"thought-train.ba9f6ea9dc.js"},{"id":"psychic-refund","mode":"reframe","name":"Psychic Refund","verb":"rub","family":"REFRAME","minutes":2,"parents":["Social / Team / Perspective","Uncertainty / Future Worry / Reassurance","Beliefs / Evidence"],"cast":["glitch","sync","patch"],"poster":{"char":"glitch","mood":"scan"},"tagline":"A fake psychic says she knows what they think. Demand a refund.","why":"For “I know what they think”: check what was said, what else it means, how to find out.","n":21,"file":"psychic-refund.1eaf2d5230.js"},{"id":"good-enough-bakery","mode":"reframe","name":"Good Enough Bakery","verb":"pipe","family":"REFRAME","minutes":2,"parents":["Getting Started","Performance / Confidence","Mental Overload / Working Memory"],"cast":["rush","patch","drop"],"poster":{"char":"rush","mood":"happy"},"tagline":"Pipe glossy icing, serve when it’s good enough, watch them love it.","why":"For perfectionism: test whether 80% delights people just as much as 100% does.","n":22,"file":"good-enough-bakery.548931449c.js"}]

